// The page where the address was seen must be a normal public web page.
// This step only checks that the address is not hallucinated, so any public site is fine.
const lead = $json;
const pageUrl = String(lead.emailSourceUrl || '').trim();

// Take the host name: the text right after "http://" or "https://".
// "@" is not allowed, so tricks like "https://x@127.0.0.1/" find no host at all.
const match = pageUrl.match(/^https?:\/\/([^\/?#:@]+)(?=[\/?#:]|$)/i);
const host = match ? match[1].toLowerCase() : '';

// Only letters, digits, dots and hyphens
const isPlainName = /^[a-z0-9.-]+$/.test(host);

// Must end in a real ending made of letters (".com", ".es"). This blocks numeric addresses of any kind.
const hasRealEnding = /\.[a-z]{2,63}$/.test(host);

// Block local names (the internal network)
const isLocal = host.endsWith('.localhost') || host.endsWith('.local') || host.endsWith('.internal');

const isSafe = isPlainName && hasRealEnding && !isLocal;

// An empty pageUrl means: do not download anything
return { json: { ...lead, pageUrl: isSafe ? pageUrl : '' } };

// The lead as it was prepared, and the page text (empty if the page could not be read)
const lead = $('Prepare Page Check').item.json;
const page = String($json.data || '').toLowerCase();
const email = String(lead.contactEmail || '').trim().toLowerCase();

// The address counts as verified only if it is written on the cited page
const verified = email !== '' && page !== '' && page.includes(email);

// Remove the helper field and return the lead
const { pageUrl, ...rest } = lead;
return { json: { ...rest, emailVerified: verified } };
